<?php
namespace Delnavazan\Platform\Core\Application; use Delnavazan\Platform\Core\Infrastructure\Repository\{StudentRepository,TeacherRepository,CourseRepository,EnrolmentRepository};
final class EnrolmentService { public function create(array $d):int{if(!current_user_can('dzn_manage_enrolments'))throw new \RuntimeException('Unauthorized');foreach([['student_id',StudentRepository::class],['teacher_id',TeacherRepository::class],['course_id',CourseRepository::class]]as[$f,$c]){$d[$f]=Normalizer::id($d[$f]??null);$r=(new $c)->usable($d[$f]);if(!$r||$r->status==='archived')throw new \InvalidArgumentException('Usable '.$f.' required');}$d['status']=Normalizer::one($d['status']??'draft',['draft','active','paused','ending','completed','cancelled'],'enrolment state');if(isset($d['preferred_weekday'])&&$d['preferred_weekday']!==null)$d['preferred_weekday']=Normalizer::count($d['preferred_weekday'],1,7);$d['preferred_local_time']=Normalizer::time($d['preferred_local_time']??null);$d['schedule_timezone']=Normalizer::timezone($d['schedule_timezone']??null);return Creator::create(new EnrolmentRepository,$d,'DZN-ENR-');} }
